<?php
require_once '../../config/db.php';$customers=$pdo->query("SELECT c.id,c.company_name,c.currency_code,COALESCE(t.name,c.contact_type) type_name FROM contacts c LEFT JOIN contact_types t ON t.id=c.contact_type_id WHERE COALESCE(t.base_kind,c.contact_type) IN('customer','both') ORDER BY c.company_name")->fetchAll();$items=$pdo->query("SELECT i.id,i.name,i.description,i.unit_price,COALESCE(t.name,i.item_type) type_name,COALESCE(tr.rate_percentage,0) tax_rate,GROUP_CONCAT(CONCAT(p.currency_code,':',p.unit_price) SEPARATOR '|') prices FROM items i LEFT JOIN item_types t ON t.id=i.item_type_id LEFT JOIN tax_rates tr ON tr.id=i.tax_rate_id LEFT JOIN item_prices p ON p.item_id=i.id WHERE i.is_active=1 GROUP BY i.id ORDER BY i.name")->fetchAll();foreach($items as &$item){$priceMap=[];foreach(explode('|',(string)$item['prices']) as $pair){if(!$pair)continue;[$code,$price]=explode(':',$pair,2);$priceMap[$code]=(float)$price;}$item['price_map']=$priceMap;}unset($item);$currencies=$pdo->query('SELECT code,name,symbol,exchange_rate FROM currencies ORDER BY is_base_currency DESC,name')->fetchAll();$taxes=$pdo->query('SELECT rate_percentage,name FROM tax_rates WHERE is_active=1 ORDER BY rate_percentage')->fetchAll();$templates=$pdo->query('SELECT id,name,is_default FROM invoice_templates ORDER BY is_default DESC,name')->fetchAll();require_once '../includes/header.php';require_once '../includes/sidebar.php';
?>
<main class="flex-1 h-screen overflow-y-auto app-scroll"><header class="bg-white border-b px-5 md:px-8 py-5 flex justify-between items-center sticky top-0 z-10"><div class="flex items-center gap-4"><button data-sidebar-toggle class="lg:hidden text-2xl">☰</button><div><h2 class="text-2xl font-bold">Create invoice</h2><p class="text-sm text-slate-500">Choose a template, currency, customer, and multi-currency item prices</p></div></div><a href="invoices.php" class="border rounded-lg px-4 py-2">Cancel</a></header><div class="p-5 md:p-8 max-w-6xl mx-auto"><form action="process_invoice.php" method="post" class="bg-white border rounded-2xl shadow-sm p-6 md:p-8"><?=csrf_field()?><div class="grid md:grid-cols-2 lg:grid-cols-5 gap-4 pb-7 border-b"><label class="text-sm lg:col-span-2">Customer<select id="customer" name="contact_id" required class="mt-1 w-full border rounded-lg px-3 py-2.5 bg-white"><option value="">Choose customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>" data-currency="<?=$c['currency_code']?>"><?=h($c['company_name'].' · '.$c['type_name'])?></option><?php endforeach;?></select></label><label class="text-sm">Currency<select id="invoiceCurrency" name="currency_code" class="mt-1 w-full border rounded-lg px-3 py-2.5 bg-white"><?php foreach($currencies as $c):?><option value="<?=$c['code']?>" data-symbol="<?=h($c['symbol'])?>"><?=h($c['code'].' · '.$c['name'])?></option><?php endforeach;?></select></label><label class="text-sm">Template<select name="invoice_template_id" class="mt-1 w-full border rounded-lg px-3 py-2.5 bg-white"><?php foreach($templates as $t):?><option value="<?=$t['id']?>" <?=$t['is_default']?'selected':''?>><?=h($t['name'])?></option><?php endforeach;?></select></label><a href="../invoice_templates.php" class="self-end text-center border rounded-lg px-3 py-2.5 brand-text text-sm font-semibold">Design templates</a><label class="text-sm">Issue date<input type="date" name="issue_date" value="<?=date('Y-m-d')?>" required class="mt-1 w-full border rounded-lg px-3 py-2.5"></label><label class="text-sm">Due date<input type="date" name="due_date" value="<?=date('Y-m-d',strtotime('+30 days'))?>" required class="mt-1 w-full border rounded-lg px-3 py-2.5"></label><label class="text-sm lg:col-span-3">Invoice notes<input name="notes" placeholder="Optional project or order reference" class="mt-1 w-full border rounded-lg px-3 py-2.5"></label></div>
<div class="mt-7"><div class="flex justify-between mb-3"><h3 class="font-bold text-lg">Line items</h3><button type="button" id="addRow" class="brand-text font-semibold">+ Add line</button></div><div class="overflow-x-auto border rounded-xl"><table class="w-full text-sm min-w-[850px]"><thead class="bg-slate-50"><tr><th class="text-left p-3 w-2/5">Item & description</th><th class="text-left p-3">Qty</th><th class="text-left p-3">Unit price</th><th class="text-left p-3">Tax</th><th class="text-right p-3">Total</th><th class="p-3"></th></tr></thead><tbody id="invoiceItems" class="divide-y"><tr class="item-row"><td class="p-3"><select name="item_id[]" required class="item-select w-full border rounded px-2 py-2"><option value="">Choose item</option><?php foreach($items as $i):?><option value="<?=$i['id']?>" data-prices="<?=h(json_encode($i['price_map']))?>" data-tax="<?=$i['tax_rate']?>" data-description="<?=h($i['description'])?>"><?=h($i['name'].' · '.$i['type_name'])?></option><?php endforeach;?></select><input name="description[]" placeholder="Description" class="mt-1 w-full border rounded px-2 py-1.5 description"></td><td class="p-3"><input type="number" name="quantity[]" value="1" min="0.001" step="0.001" class="qty w-24 border rounded px-2 py-2"></td><td class="p-3"><input type="number" name="unit_price[]" value="0.00" min="0" step="0.01" class="price w-32 border rounded px-2 py-2"></td><td class="p-3"><select name="tax_rate[]" class="tax-rate border rounded px-2 py-2 bg-white"><?php foreach($taxes as $t):?><option value="<?=$t['rate_percentage']?>"><?=h($t['name'])?></option><?php endforeach;?></select></td><td class="p-3 text-right font-bold row-total">0.00</td><td class="p-3"><button type="button" class="remove-row text-rose-600 text-xl">×</button></td></tr></tbody></table></div></div>
<div class="grid md:grid-cols-2 gap-8 mt-7"><label class="text-sm">Terms<textarea name="terms" rows="4" class="mt-1 w-full border rounded-lg px-3 py-2.5"><?=h(setting($pdo,'invoice_terms'))?></textarea></label><div class="ml-auto w-full max-w-sm space-y-3"><p class="flex justify-between"><span>Subtotal</span><strong id="subtotal">0.00</strong></p><p class="flex justify-between"><span>Tax</span><strong id="totalTax">0.00</strong></p><p class="flex justify-between text-xl border-t pt-3"><strong>Total</strong><strong id="grandTotal" class="brand-text">0.00</strong></p><button class="brand-bg text-white rounded-lg px-6 py-3 font-semibold w-full">Create and post invoice</button></div></div></form></div></main>
<script>const tbody=document.getElementById('invoiceItems'),currency=document.getElementById('invoiceCurrency'),customer=document.getElementById('customer');function symbol(){return currency.selectedOptions[0]?.dataset.symbol||''}function setItem(row){const opt=row.querySelector('.item-select').selectedOptions[0];let prices={};try{prices=JSON.parse(opt.dataset.prices||'{}')}catch{}row.querySelector('.price').value=Number(prices[currency.value]??0).toFixed(2);row.querySelector('.description').value=opt.dataset.description||opt.textContent.split(' · ')[0].trim();const tax=Number(opt.dataset.tax||0);[...row.querySelector('.tax-rate').options].forEach(o=>o.selected=Number(o.value)===tax)}function calculate(){let sub=0,tax=0;tbody.querySelectorAll('.item-row').forEach(r=>{const base=(Number(r.querySelector('.qty').value)||0)*(Number(r.querySelector('.price').value)||0),t=base*(Number(r.querySelector('.tax-rate').value)||0)/100;sub+=base;tax+=t;r.querySelector('.row-total').textContent=symbol()+(base+t).toFixed(2)});document.getElementById('subtotal').textContent=symbol()+sub.toFixed(2);document.getElementById('totalTax').textContent=symbol()+tax.toFixed(2);document.getElementById('grandTotal').textContent=symbol()+(sub+tax).toFixed(2)}tbody.addEventListener('change',e=>{const r=e.target.closest('.item-row');if(e.target.classList.contains('item-select'))setItem(r);calculate()});tbody.addEventListener('input',calculate);tbody.addEventListener('click',e=>{if(e.target.classList.contains('remove-row')&&tbody.children.length>1){e.target.closest('tr').remove();calculate()}});document.getElementById('addRow').onclick=()=>{const row=tbody.firstElementChild.cloneNode(true);row.querySelector('.item-select').value='';row.querySelector('.description').value='';row.querySelector('.qty').value=1;row.querySelector('.price').value='0.00';row.querySelector('.row-total').textContent='0.00';tbody.append(row)};currency.onchange=()=>{tbody.querySelectorAll('.item-row').forEach(r=>{if(r.querySelector('.item-select').value)setItem(r)});calculate()};customer.onchange=()=>{const code=customer.selectedOptions[0]?.dataset.currency;if(code){currency.value=code;currency.dispatchEvent(new Event('change'))}};calculate();</script><?php require_once '../includes/footer.php';?>
